-- Physical extensions for Supabase PostgreSQL application functionality.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS auth_account (account_id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('PASSENGER','DRIVER','ADMIN')), user_id TEXT UNIQUE REFERENCES app_user(user_id) ON DELETE CASCADE, driver_id TEXT UNIQUE REFERENCES driver(driver_id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trip_event (event_id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text, trip_id TEXT NOT NULL REFERENCES trip(trip_id) ON DELETE CASCADE, actor_id TEXT, event_type TEXT NOT NULL, previous_status TEXT, new_status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE driver ADD COLUMN IF NOT EXISTS availability_status TEXT NOT NULL DEFAULT 'OFFLINE' CHECK (availability_status IN ('ONLINE','OFFLINE','ON_TRIP'));
ALTER TABLE driver ADD COLUMN IF NOT EXISTS verification_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING','VERIFIED','REJECTED'));
ALTER TABLE driver ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE vehicle ADD COLUMN IF NOT EXISTS registration_number TEXT;
ALTER TABLE vehicle ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE vehicle_document ADD COLUMN IF NOT EXISTS document_type TEXT NOT NULL DEFAULT 'RC';
ALTER TABLE vehicle_document ADD COLUMN IF NOT EXISTS document_url TEXT;
ALTER TABLE trip ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED','ASSIGNED','ACCEPTED','IN_PROGRESS','COMPLETED','CANCELLED'));
ALTER TABLE trip ADD COLUMN IF NOT EXISTS distance_km NUMERIC(10,2);
ALTER TABLE trip ADD COLUMN IF NOT EXISTS estimated_fare NUMERIC(12,2);
ALTER TABLE trip ADD COLUMN IF NOT EXISTS final_fare NUMERIC(12,2);
ALTER TABLE trip ADD COLUMN IF NOT EXISTS requested_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE trip ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ;
ALTER TABLE trip ADD COLUMN IF NOT EXISTS completed_at TIMESTAMPTZ;
ALTER TABLE trip ADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMPTZ;
ALTER TABLE trip ADD COLUMN IF NOT EXISTS cancellation_reason TEXT;
ALTER TABLE payment ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PAID','FAILED','REFUNDED'));
ALTER TABLE payment ADD COLUMN IF NOT EXISTS transaction_reference TEXT;
ALTER TABLE payment ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT now();
